export async function getInvoice(id: string) {
  const { data, error } = await supabase.from('invoices').select('*').eq('id', id).single();
  if (error) throw new Error(`DB error: ${error.message}`);
  if (!data) throw new Error('Invoice not found');
  return data;
}

